import glob
import os

_xauth = os.environ.get("XAUTHORITY")
if not _xauth or not os.path.exists(_xauth):
    _runtime_dir = os.environ.get("XDG_RUNTIME_DIR", f"/run/user/{os.getuid()}")
    _candidates = sorted(
        glob.glob(os.path.join(_runtime_dir, ".mutter-Xwaylandauth.*")),
        key=os.path.getmtime,
        reverse=True,
    )
    if _candidates:
        os.environ["XAUTHORITY"] = _candidates[0]

